public enum RideStatus { Requested, Matched, InProgress, Completed, Cancelled }

public class Rider
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Name { get; set; }
    public (double Lat, double Lng) CurrentLocation { get; set; }
}

public class Driver
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Name { get; set; }
    public string LicensePlate { get; set; }
    public (double Lat, double Lng) CurrentLocation { get; set; }
    public bool IsAvailable { get; set; }
}

public class Ride
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid RiderId { get; set; }
    public Guid? DriverId { get; set; }
    public RideStatus Status { get; private set; } = RideStatus.Requested;
    public (double Lat, double Lng) Pickup { get; set; }
    public (double Lat, double Lng) Dropoff { get; set; }
    public decimal Fare { get; private set; }

    public void AssignDriver(Guid driverId)
    {
        if (Status != RideStatus.Requested) return;
        DriverId = driverId;
        Status = RideStatus.Matched;
    }

    public void Start()
    {
        if (Status != RideStatus.Matched) return;
        Status = RideStatus.InProgress;
        Fare = CalculateFare();
    }

    public void Complete() => Status = RideStatus.Completed;

    private decimal CalculateFare()
    {
        var distance = Haversine(Pickup, Dropoff);
        return 2.0m + distance * 1.5m; // base + per-km
    }
}
